package com.example.starter.battery;

/**
 * 电池资产状态。
 */
public enum BatteryStatus {
    /** 在库待检（入站后未检测）。 */
    PENDING_INSPECTION,
    /** 充电/待修（检测不达标）。 */
    CHARGING,
    /** 上架可换（检测达标）。 */
    LISTED,
    /** 换出在用（车辆侧）。 */
    IN_USE,
    /** 站间调拨在途。 */
    IN_TRANSIT,
    /** 调拨异常（在途超 24 小时，待人工核销）。 */
    TRANSFER_EXCEPTION
}

package com.example.starter.battery;

/**
 * 电池流转事件类型，事件按序构成哈希链。
 */
public enum EventType {
    /** 建档。 */
    REGISTER,
    /** 入站。 */
    INBOUND,
    /** 检测（结论不可修改，复检走新批次）。 */
    INSPECTION,
    /** 上架可换。 */
    LISTED,
    /** 换出绑定车辆。 */
    SWAP_OUT,
    /** 站间调拨发出（在途）。 */
    TRANSFER_OUT,
    /** 到站签收。 */
    TRANSFER_SIGN,
    /** 在途超 24 小时自动转调拨异常。 */
    TRANSFER_EXCEPTION,
    /** 异常人工核销。 */
    WRITE_OFF,
    /** 链不一致等异常告警。 */
    ALARM
}

package com.example.starter.battery;

/**
 * 站间调拨单状态。
 */
public enum TransferStatus {
    /** 在途。 */
    IN_TRANSIT,
    /** 已签收。 */
    SIGNED,
    /** 调拨异常（在途超 24 小时）。 */
    EXCEPTION,
    /** 异常已人工核销（仅可核销一次）。 */
    WRITTEN_OFF
}

