private BatteryEvent appendEvent(String code, EventType type, String payload) {
    Optional<BatteryEvent> latest = eventRepo.findLatest(code);
    long seq = latest.map(e -> e.seq() + 1).orElse(1L);
    String prevHash = latest.map(BatteryEvent::hash).orElse(Hashes.GENESIS_PREV_HASH);
    long now = time.nowMillis();
    String hash = Hashes.sha256(code + "|" + seq + "|" + type.name() + "|" + payload + "|" + prevHash + "|" + now);
    BatteryEvent event = new BatteryEvent(0, code, seq, type, payload, prevHash, hash, now);
    eventRepo.append(event);
    return event;
}
```

