public boolean verifyChain(String code) {
    List<BatteryEvent> events = eventRepo.findChain(code);
    String prev = Hashes.GENESIS_PREV_HASH;
    long expectedSeq = 1;
    for (BatteryEvent e : events) {
        if (e.seq() != expectedSeq) return false;
        if (!e.prevHash().equals(prev)) return false;
        String recomputed = Hashes.sha256(e.batteryCode() + "|" + e.seq() + "|" + e.eventType().name() + "|" + e.payload() + "|" + e.prevHash() + "|" + e.createdAt());
        if (!recomputed.equals(e.hash())) return false;
        prev = e.hash();
        expectedSeq++;
    }
    return true;
}
